import{_ as e,c as o,o as r,ax as n}from"./chunks/framework.DHqKNX4U.js";const g=JSON.parse('{"title":"Google Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/sso/examples/google-workspace.md","filePath":"enterprise/sso/examples/google-workspace.md"}'),a={name:"enterprise/sso/examples/google-workspace.md"};function i(s,t,d,l,c,h){return r(),o("div",null,t[0]||(t[0]=[n('<h1 id="google-workspace" tabindex="-1">Google Workspace <a class="header-anchor" href="#google-workspace" aria-label="Permalink to &quot;Google Workspace&quot;">​</a></h1><p>Connect Open Archiver directly to Google Workspace so that people sign in with their Google account.</p><p>Google Workspace works with both protocols Open Archiver supports, but they are not equivalent. Choose before you start, because switching later means reconfiguring both sides.</p><table tabindex="0"><thead><tr><th></th><th>OpenID Connect</th><th>SAML 2.0</th></tr></thead><tbody><tr><td>Administrative rights required</td><td>A Google Cloud project</td><td>Google Workspace <strong>super admin</strong></td></tr><tr><td>Group-based role assignment</td><td><strong>Not available</strong></td><td>Available</td></tr><tr><td>Typical setup time</td><td>About 10 minutes</td><td>About 25 minutes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Google Workspace does not release group membership over OpenID Connect</p><p>Google publishes no group information in its OpenID Connect tokens, so group mappings can never match on an OpenID Connect connection and every user receives the default role. If directory groups must determine Open Archiver roles, use SAML 2.0 — or place <a href="./google-workspace-okta.html">Okta in front of Google Workspace</a>, which provides groups over either protocol.</p></div><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Detail</th></tr></thead><tbody><tr><td>License</td><td>Open Archiver Enterprise with the <strong>SSO</strong> feature enabled</td></tr><tr><td>Open Archiver role</td><td>Super Admin — single sign-on is configured under <strong>Admin → Single Sign-On</strong></td></tr><tr><td>Google rights</td><td>A Google Cloud project for OpenID Connect; Google Workspace <strong>super admin</strong> for SAML</td></tr><tr><td>Application address</td><td><code>APP_URL</code> must be set to the address people use to reach Open Archiver. Every address exchanged with Google derives from it.</td></tr></tbody></table><p>Open <strong>Admin → Single Sign-On</strong> in Open Archiver and start a new connection before configuring Google. The form displays the exact addresses to register, and copying them from the page is more reliable than retyping them from this document.</p><table tabindex="0"><thead><tr><th>Address</th><th>Used by</th><th>Example</th></tr></thead><tbody><tr><td><strong>Redirect URI</strong></td><td>OpenID Connect</td><td><code>https://archive.example.com/signin/sso/callback</code></td></tr><tr><td><strong>Service provider metadata URL</strong></td><td>SAML 2.0</td><td><code>https://archive.example.com/api/v1/enterprise/sso/saml/metadata</code></td></tr><tr><td><strong>Assertion consumer service (ACS) URL</strong></td><td>SAML 2.0</td><td><code>https://archive.example.com/signin/sso/callback/saml</code></td></tr></tbody></table><p>Throughout this document, <code>archive.example.com</code> stands for your own Open Archiver address and <code>example.com</code> for your own Workspace domain.</p><hr><h2 id="openid-connect" tabindex="-1">OpenID Connect <a class="header-anchor" href="#openid-connect" aria-label="Permalink to &quot;OpenID Connect&quot;">​</a></h2><h3 id="part-1-—-create-the-oauth-client-in-google-cloud" tabindex="-1">Part 1 — Create the OAuth client in Google Cloud <a class="header-anchor" href="#part-1-—-create-the-oauth-client-in-google-cloud" aria-label="Permalink to &quot;Part 1 — Create the OAuth client in Google Cloud&quot;">​</a></h3><ol><li><p>Open the <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud console</a> and select or create a project.</p></li><li><p>Go to <strong>APIs &amp; Services → OAuth consent screen</strong> and set <strong>User type</strong> to <strong>Internal</strong>.</p><p>Internal restricts sign-in to accounts in your own Workspace domain and avoids Google&#39;s application verification review. External is not appropriate here.</p></li><li><p>Go to <strong>APIs &amp; Services → Credentials → Create credentials → OAuth client ID</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Application type</td><td><strong>Web application</strong></td></tr><tr><td>Name</td><td>For example, <code>Open Archiver</code></td></tr><tr><td>Authorised redirect URIs</td><td><code>https://archive.example.com/signin/sso/callback</code></td></tr></tbody></table><p>The redirect URI must match the address shown in Open Archiver character for character, including the scheme and any trailing path. Google rejects a sign-in whose redirect URI differs in any way from a registered value.</p></li><li><p>Copy the <strong>Client ID</strong> and <strong>Client secret</strong>. The secret is shown once.</p></li></ol><h3 id="part-2-—-create-the-connection-in-open-archiver" tabindex="-1">Part 2 — Create the connection in Open Archiver <a class="header-anchor" href="#part-2-—-create-the-connection-in-open-archiver" aria-label="Permalink to &quot;Part 2 — Create the connection in Open Archiver&quot;">​</a></h3><p>Complete all three sections of the connection form. Fields not listed here can keep their defaults.</p><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td><strong>OpenID Connect</strong></td></tr><tr><td>Display name</td><td><code>Google</code> — appears on the sign-in page as &quot;Continue with Google&quot;</td></tr><tr><td>Issuer URL</td><td><code>https://accounts.google.com</code></td></tr><tr><td>Client ID</td><td>From Part 1</td></tr><tr><td>Client secret</td><td>From Part 1. Stored encrypted and not displayed again after saving.</td></tr></tbody></table><p><strong>Accounts</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Allowed email domains</td><td><code>example.com</code> — your Workspace domain. At least one entry is required. Press Enter after each domain to add it.</td></tr><tr><td>Create accounts on first sign-in</td><td><strong>On</strong>, so people receive an account the first time they sign in. Turn it off to restrict access to accounts you create.</td></tr><tr><td>Link to existing accounts</td><td><strong>On</strong>, so a person who already has an Open Archiver account keeps it rather than being refused.</td></tr></tbody></table><p><strong>Roles</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Groups claim</td><td>Leave as <code>groups</code>. Google sends nothing here, so the value has no effect on this connection.</td></tr><tr><td><strong>Default role</strong></td><td><strong>Required.</strong> Every person signing in through this connection receives this role.</td></tr><tr><td>Group mappings</td><td>Leave empty — they cannot match on an OpenID Connect connection to Google.</td></tr><tr><td>Update roles on every sign-in</td><td>Has no effect without group mappings; either setting is acceptable.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">A default role is mandatory on this connection</p><p>Because Google sends no group information, no mapping can ever match. Open Archiver refuses to create an account that resolves to no role at all, rather than admitting someone who can see nothing — so without a default role, account creation fails on the first sign-in.</p></div><h3 id="part-3-—-test-then-enable" tabindex="-1">Part 3 — Test, then enable <a class="header-anchor" href="#part-3-—-test-then-enable" aria-label="Permalink to &quot;Part 3 — Test, then enable&quot;">​</a></h3><ol><li>Select <strong>Test connection</strong>. A successful test confirms Open Archiver can reach Google and read its configuration. Resolve any failure before continuing.</li><li>Turn on <strong>Enable this connection</strong>.</li><li>Save.</li></ol><p>A <strong>Continue with Google</strong> button now appears on the sign-in page.</p><hr><h2 id="saml-2-0" tabindex="-1">SAML 2.0 <a class="header-anchor" href="#saml-2-0" aria-label="Permalink to &quot;SAML 2.0&quot;">​</a></h2><p>Google requires an <strong>HTTPS</strong> assertion consumer service address, which any production deployment satisfies. You need Google Workspace <strong>super admin</strong> rights.</p><h3 id="part-1-—-create-the-custom-saml-application-in-google" tabindex="-1">Part 1 — Create the custom SAML application in Google <a class="header-anchor" href="#part-1-—-create-the-custom-saml-application-in-google" aria-label="Permalink to &quot;Part 1 — Create the custom SAML application in Google&quot;">​</a></h3><p>In the <a href="https://admin.google.com/" target="_blank" rel="noreferrer">Google Admin console</a>, go to <strong>Apps → Web and mobile apps → Add app → Add custom SAML app</strong>.</p><ol><li><p><strong>App details</strong> — name the application, for example <code>Open Archiver</code>.</p></li><li><p><strong>Google Identity Provider details</strong> — select <strong>Download metadata</strong> and keep the XML file. You will paste its contents into Open Archiver.</p></li><li><p><strong>Service provider details</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>ACS URL</td><td><code>https://archive.example.com/signin/sso/callback/saml</code></td></tr><tr><td>Entity ID</td><td><code>https://archive.example.com/api/v1/enterprise/sso/saml/metadata</code></td></tr><tr><td>Name ID format</td><td><strong>EMAIL</strong></td></tr><tr><td>Name ID</td><td><strong>Basic Information → Primary email</strong></td></tr></tbody></table><p>Leave <strong>Signed response</strong> at its default. Open Archiver validates the signature on the assertion.</p></li><li><p><strong>Attribute mapping</strong> — add a <strong>Group membership</strong> mapping:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Google groups</td><td>Select the groups relevant to Open Archiver (up to 75)</td></tr><tr><td>App attribute</td><td><code>Groups</code></td></tr></tbody></table><p>Note the capital G. The name you enter here must be reproduced exactly in Open Archiver.</p></li><li><p><strong>User access</strong> — turn the application <strong>ON for everyone</strong>, or on for the organisational units that should have access. A person outside the enabled scope receives an access error from Google before reaching Open Archiver.</p></li></ol><p>Google can take several minutes to make a newly created application available.</p><h3 id="part-2-—-create-the-connection-in-open-archiver-1" tabindex="-1">Part 2 — Create the connection in Open Archiver <a class="header-anchor" href="#part-2-—-create-the-connection-in-open-archiver-1" aria-label="Permalink to &quot;Part 2 — Create the connection in Open Archiver&quot;">​</a></h3><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td><strong>SAML 2.0</strong></td></tr><tr><td>Display name</td><td><code>Google</code></td></tr><tr><td>IdP metadata URL</td><td>The metadata address from Google&#39;s console</td></tr><tr><td>IdP metadata XML</td><td>Paste the file downloaded in Part 1. When present, this takes precedence over the URL and is the more reliable option with Google.</td></tr></tbody></table><p><strong>Accounts</strong> — as for OpenID Connect above.</p><p><strong>Roles</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Groups claim</td><td><code>Groups</code> — exactly as entered in Part 1, including capitalisation</td></tr><tr><td>Group mappings</td><td>The Google group&#39;s <strong>email address</strong> on the left, the Open Archiver role on the right</td></tr><tr><td>Default role</td><td>Recommended, as the fallback for anyone matching no mapping</td></tr><tr><td>Update roles on every sign-in</td><td><strong>On</strong>, so moving a person between Google groups updates their role at the next sign-in</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Google identifies groups by email address</p><p>Enter <code>engineering@example.com</code>, not <code>Engineering</code>. Matching is exact and case-sensitive. A sign-in that succeeds but grants the default role instead of the mapped one is almost always caused by a mismatch here.</p></div><h3 id="part-3-—-test-then-enable-1" tabindex="-1">Part 3 — Test, then enable <a class="header-anchor" href="#part-3-—-test-then-enable-1" aria-label="Permalink to &quot;Part 3 — Test, then enable&quot;">​</a></h3><p>As for OpenID Connect. A successful SAML test reports the sign-in address and the number of signing certificates found in the metadata.</p><hr><h2 id="verify-the-first-sign-in" tabindex="-1">Verify the first sign-in <a class="header-anchor" href="#verify-the-first-sign-in" aria-label="Permalink to &quot;Verify the first sign-in&quot;">​</a></h2><p>Sign in from a private browser window, so an existing Google session does not mask the flow.</p><ol><li>Open the Open Archiver sign-in page and select <strong>Continue with Google</strong>.</li><li>Complete Google&#39;s sign-in.</li><li>Confirm you arrive at the dashboard.</li></ol><p>Then check the following as an administrator:</p><table tabindex="0"><thead><tr><th>Where</th><th>What to confirm</th></tr></thead><tbody><tr><td><strong>Settings → Users</strong></td><td>The account exists with the expected role — the mapped role on SAML, the default role on OpenID Connect</td></tr><tr><td><strong>Compliance → Audit Log</strong></td><td>An account-creation entry for a first sign-in, and a sign-in entry for every sign-in</td></tr><tr><td><strong>Settings → Account</strong> (as that user)</td><td>Password management is hidden for accounts created through single sign-on</td></tr></tbody></table><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Failed sign-ins show the same brief message to the person signing in. The explanation is recorded in <strong>Compliance → Audit Log</strong>, where each failed sign-in entry names the connection, the address the provider supplied, and the domains the connection permits.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Resolution</th></tr></thead><tbody><tr><td>Sign-in fails; audit log reports a domain that is not allowed</td><td>The address Google supplied is not in <strong>Allowed email domains</strong></td><td>Add the domain shown in the audit entry, or correct the account being used</td></tr><tr><td>Sign-in fails; audit log reports no role could be determined</td><td>A new account matched no group mapping and no default role is set</td><td>Set a <strong>Default role</strong></td></tr><tr><td>Sign-in succeeds but the role is the default, not the mapped one</td><td>The groups claim name or the group values do not match</td><td>Confirm <strong>Groups claim</strong> is <code>Groups</code>, and that mappings use group email addresses</td></tr><tr><td>Google reports that the application is not available</td><td>The application is off for that person&#39;s organisational unit</td><td>In the Google Admin console, turn the application on for their organisational unit</td></tr><tr><td>Google rejects the redirect address</td><td>The registered redirect URI differs from the one Open Archiver uses</td><td>Copy the redirect URI from the Open Archiver connection form and register it exactly</td></tr><tr><td>No sign-in button appears</td><td>The connection is not enabled, or the license does not include SSO</td><td>Enable the connection; confirm the license under <strong>Admin → License</strong></td></tr></tbody></table><hr><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><strong>Group limit.</strong> Google includes at most 75 groups in a SAML response. Select only the groups relevant to Open Archiver.</li><li><strong>Account selection.</strong> Google offers whichever accounts the browser is already signed in to. The allowed-domain list is what prevents other accounts from gaining access, so a refusal occurs after Google&#39;s account chooser rather than before it.</li><li><strong>Signing out.</strong> Signing out of Open Archiver does not end the Google session. Use a private window when testing repeatedly.</li></ul><p>For the roles model, running several providers at once, and requiring single sign-on, see the <a href="./../guide.html">SSO guide</a>.</p>',56)]))}const u=e(a,[["render",i]]);export{g as __pageData,u as default};
